{"description": "Run echo command and catch missing file read", "code": "const result: Record<string, unknown> = {};

const shell = await tools.pwsh({ command: "echo CODE_ROUND_OK", description: "Echo CODE_ROUND_OK marker" });
result.echo = shell.kind === "foreground"
  ? { exitCode: shell.exitCode, stdout: shell.stdout.text.trim(), stderr: shell.stderr.text.trim() }
  : shell;

try {
  const r = await tools.read({ file_path: "missing.txt" });
  result.read = { ok: true, lines: r.lines.map((l) => l.text) };
} catch (err) {
  result.read = {
    ok: false,
    errorName: err instanceof Error ? err.name : typeof err,
    message: err instanceof Error ? err.message : String(err),
  };
}

console.log(JSON.stringify(result, null, 2));
return result;"}

